import React from "react";
import { render, fireEvent, screen } from "@testing-library/react";
import { composeStories } from "@storybook/react";
import { axe } from "jest-axe";
import * as stories from "./Toast.stories";
import Toast from ".";

const { Basic } = composeStories(stories) as any;

describe("Banner component", () => {
  it("pass A11Y", async () => {
    const { container } = render(<Basic />);
    const results = await axe(container);
    expect(results).toHaveNoViolations();
  });

  it("passes through props", () => {
    render(<Toast data-testid="toast">Hello world</Toast>);
    expect(screen.queryByRole("status")).toHaveAttribute(
      "data-testid",
      "toast"
    );
  });

  it("has no close button by default", () => {
    render(<Toast>Hello world</Toast>);
    expect(screen.queryByRole("button", { name: /Remove/i })).toBeNull();
  });

  it("calls onClose when the close button is clicked", () => {
    jest.useFakeTimers();
    const callback = jest.fn();
    render(
      <Toast allowClose onClose={callback}>
        Hello world
      </Toast>
    );
    fireEvent.click(screen.getByRole("button", { name: /Remove/i }));
    expect(callback).toHaveBeenCalledTimes(1);
  });

  it("calls onClose after an `autoHide` duration", () => {
    jest.useFakeTimers();
    const callback = jest.fn();
    render(
      <>
        <Toast autoHideDuration={3} onClose={callback}>
          Hello world
        </Toast>
        <Toast autoHideDuration={6} onClose={callback}>
          Hello world
        </Toast>
        <Toast autoHideDuration={9} onClose={callback}>
          Hello world
        </Toast>
      </>
    );
    jest.runAllTimers();
    expect(callback).toHaveBeenCalledTimes(3);
  });
});
